{
  "understanding": {
    "purpose": "帮助开发者根据 API 错误码和错误信息定位原因，并查找对应的解决办法。",
    "reading": "读者通常先扫描错误码或错误信息找到目标行，再横向阅读含义和解决办法；比较多个错误时，需要保持每行的对应关系清晰。",
    "groups": [
      "错误码与错误信息共同标识错误，适合保持紧凑并便于快速扫描。",
      "含义与解决办法共同构成排查内容：前者解释原因，后者指导操作，应获得大部分宽度。"
    ],
    "keep_intact": [
      "错误码数字",
      "INVALID_APPID、INVALID_CREDENTIAL 等错误信息标识符",
      "AppID、access_token、AppSecret、OpenID 等技术标识符"
    ],
    "may_wrap": [
      "含义中的中文解释可按自然语义换行。",
      "解决办法中的中文步骤和说明可换行；较长的解决办法通常决定行高，其他列的换行可利用这部分行高。"
    ]
  },
  "designs": [
    {
      "name": "A",
      "widths": [70, 175, 190, 284],
      "idea": "均衡排查：保持两列标识完整，为解决办法分配较多宽度，同时给含义留出舒适的阅读空间。"
    },
    {
      "name": "B",
      "widths": [70, 175, 240, 234],
      "idea": "侧重原因比较：加宽含义列，方便纵向比较不同错误的成因，接受解决办法产生更多换行。"
    },
    {
      "name": "C",
      "widths": [70, 175, 135, 339],
      "idea": "侧重操作步骤：压缩含义列以充分展开解决办法，利用解决办法形成的行高容纳原因说明的换行。"
    }
  ]
}
